
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_k_revapbeint_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_k_revapbeint", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([9.402990957733667e+01, 9.037832830264529e+01, 8.538571194985452e+01, 7.870908310206086e+01, 7.005901717478272e+01, 5.934771951062072e+01, 4.690842675519655e+01, 3.370945642442075e+01, 2.134849009408254e+01, 1.152889022946380e+01, 5.155873948673402e+00, 2.537293900473051e+00, 1.907543451501773e+00, 1.267488316327722e+00, 6.460705792534688e-01, 2.509179729799723e-01, 6.878065951928986e-02, 9.136125493522999e-03, 4.290760354440895e-04, 5.387155099448787e-06]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


